// All minimum balanced cuts, complement canonicalized. Input 22 red adjacency masks.
use std::io::{self,BufRead};fn main(){for l in io::stdin().lock().lines(){let a:Vec<u32>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();assert_eq!(a.len(),22);let d:Vec<i32>=a.iter().map(|x|x.count_ones()as i32).collect();let(mut s,mut cut,mut size,mut best)=(0u32,0,0,999);let mut ms=vec![];for i in 1u32..1<<21{let j=i.trailing_zeros()as usize;let t=1-2*((s>>j)&1)as i32;cut+=t*(d[j]-2*(s&a[j]).count_ones()as i32);s^=1<<j;size+=t;if size==11 && cut<=best{if cut<best{ms.clear();best=cut}ms.push(s)}}print!("{}",best);for x in ms{print!(" {}",x)}println!()}}
